import Status from "../../components/Status";
import FullPresent from "../../components/FullPresent";
import BentoCard from "../../components/BentoCard";
import {
  saknUrls,
  sakOverview,
  sakProjectStatus,
  realTimeInventory,
} from "../../constrains/data";

export default function ManageCRM() {
  const { projectName, title, desc } = sakOverview;
  const { title00, desc00, img00 } = realTimeInventory;

  return (
    <>
      <div className="compact-page">
        <FullPresent
          projectName={projectName}
          title={title}
          desc={desc}
          liveUrls={saknUrls}
          padding={"24px 0"}
        />
        <div className="container">
          <div className="mt-3">
            <div className="row justify-content-between mt-3 mt-md-5">
              {sakProjectStatus.map((item, index) => (
                <div key={index} className="col-sm-12 col-lg-3 pe-0 mb-5">
                  <Status title={item.title} collection={item.collection} />
                </div>
              ))}
            </div>
          </div>
          <div className="row">
            <div className="col-12">
              <BentoCard
                title={title00}
                desc={desc00}
                img={img00}
              />
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
